function renderWildlife(){for(const a of current.ecologySystem?.wildlife||[]){if(!a.active)continue;const made=animalGraphics(a),p=wp(a.position);made.c.position.set(p.x,p.y);made.c._data=a;addWorld(made.c,p.y,7,{kind:`wildlife-${a.species}`,tier:'wildlife',sourceId:a.id,height:made.h});wildlifeSprites.set(a.id,made.c)}}
function updateWildlife(t){for(const a of current.ecologySystem?.wildlife||[]){const c=wildlifeSprites.get(a.id);if(!c)continue;const p=wp(wildlifePos(a)),from=a.movement?.from||a.position,to=a.movement?.to||a.position,moving=Math.hypot((to.x||0)-(from.x||0),(to.y||0)-(from.y||0))>.4;c.position.set(p.x,p.y);c.zIndex=worldZ(p.y,7);if(c._debug){c._debug.screenX=p.x;c._debug.screenBaseY=p.y;c._debug.zIndex=c.zIndex}const g=c._animal?.g;if(g){const dx=(to.x||0)-(from.x||0);if(Math.abs(dx)>.08)g.scale.x=dx<0?-1:1;const pace=a.activity==='flee'?1.8:a.species==='rabbit'?1.15:1;g.y=moving?Math.sin(t*(a.species==='rabbit'?10:a.species==='deer'?6.5:3.5)*pace+hash(a.id)%7)*(a.activity==='flee'?1.8:1.05):Math.sin(t*2+hash(a.id)%5)*.28;if(a.species==='fish')g.rotation=Math.sin(t*2+hash(a.id)%11)*.08}c._animal.name.scale.set(1/camera.scale)}}
function progress(){if(!current)return 1;const t=current.meta?.lastAdvancedAt?new Date(current.meta.lastAdvancedAt).getTime():Date.now(),period=(current.meta?.heartbeatMinutes||5)*60000;return clamp((Date.now()-t)/period,0,1)}
function phase(a){const plan=a.activeAction,p=progress();if(!plan?.phases?.length)return{phase:'idle',label:'Between actions',x:a.coordinates?.x??50,y:a.coordinates?.y??50};const ph=plan.phases.find(x=>p>=x.start&&p<x.end)||plan.phases.at(-1),from=plan.from||a.coordinates,to=plan.to||a.coordinates;let x=to.x,y=to.y;if(plan.moving){const tr=plan.phases.find(x=>x.id==='travel');if(tr&&p<tr.start){x=from.x;y=from.y}else if(tr&&p<tr.end){const q=clamp((p-tr.start)/(tr.end-tr.start),0,1);x=from.x+(to.x-from.x)*q;y=from.y+(to.y-from.y)*q}}return{phase:ph.id,label:ph.label,x,y}}
