function actionFrame(a){if(!a)return{x:W*.55,y:W*.62,scale:1.35};const s=phase(a),pts=[wp(s)],plan=a.activeAction||{},travelling=s.phase==='travel';if(travelling&&plan.to)pts.push(wp(plan.to));if(travelling&&plan.from)pts.push(wp(plan.from));const social=/talk|teach|share|speak/i.test(`${a.currentAction||''} ${a.mind?.intent||''}`);if(social){const other=current?.agents?.find(x=>x.id!==a.id);if(other)pts.push(wp(phase(other)))}let minX=Math.min(...pts.map(p=>p.x)),maxX=Math.max(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),maxY=Math.max(...pts.map(p=>p.y));const mobile=app.screen.width<650,safeW=app.screen.width*(mobile?.88:.76),safeH=app.screen.height*(mobile?.48:.70),spanX=Math.max(120,maxX-minX),spanY=Math.max(100,maxY-minY),pad=mobile?150:210;let scale=clamp(Math.min(safeW/(spanX+pad),safeH/(spanY+pad)),mobile?1.05:.82,mobile?2.02:1.72);if(pts.length===1||Math.max(spanX,spanY)<150)scale=mobile?1.82:1.5;return{x:(minX+maxX)/2,y:(minY+maxY)/2,scale}}
