async function changeAIControl(el){const people={},body={};if(el.dataset.ai==='wildlife')body.wildlifeEnabled=el.checked;else people[el.dataset.ai]=el.checked;if(Object.keys(people).length)body.people=people;let key=localStorage.getItem('chatgptfarm-control-key');if(!key){key=prompt('Owner control key');if(!key){el.checked=!el.checked;return}localStorage.setItem('chatgptfarm-control-key',key)}const note=$('#ownerControlNote');if(note)note.textContent='Updating canonical controls…';try{const r=await fetch('/api/control',{method:'POST',headers:{'Content-Type':'application/json','X-Control-Key':key},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw Error(data.error||String(r.status));current.settings||={};current.settings.ai=data.control.ai;renderPulse();if(note)note.textContent='Saved. The next world heartbeat will use this setting.'}catch(e){el.checked=!el.checked;if(note)note.textContent=e.message==='owner_controls_not_configured'?'Owner controls need CONTROL_KEY + GITHUB_CONTROL_TOKEN in Vercel once; current safe defaults remain active.':`Control update failed: ${e.message}`;if(e.message==='unauthorized')localStorage.removeItem('chatgptfarm-control-key')}}
